use crate::theme::Theme;
use notepad_core::editor::EditorBuffer;
use notepad_core::{AppInfo,ColorOrder,FileManager,FindMatch,FindOptions,HighlightStats,LineColour,LineEnding,LineMetadata,LoadedFile,Note,NoteData,NotesStore,Result,SessionData,SessionStore,SessionTab,Settings,SettingsStore,TextEncoding,WindowState};
use rfd::FileDialog;
use serde_json::Value;
use std::fs;
use std::path::{Path,PathBuf};
use std::sync::{Mutex,RwLock};

#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum WindowCommand{Minimize,ToggleMaximize,ConfirmClose,Close}
#[derive(Debug,Clone)]pub struct DocumentState{pub path:Option<PathBuf>,pub title:String,pub buffer:EditorBuffer,pub encoding:TextEncoding,pub line_ending:LineEnding,pub had_bom:bool,pub dirty:bool}
impl Default for DocumentState{fn default()->Self{Self{path:None,title:"Untitled".into(),buffer:EditorBuffer::default(),encoding:TextEncoding::Utf8,line_ending:LineEnding::Lf,had_bom:false,dirty:false}}}
impl DocumentState{fn loaded(f:LoadedFile)->Self{let title=f.path.file_name().and_then(|n|n.to_str()).unwrap_or("Untitled").into();Self{path:Some(f.path),title,buffer:EditorBuffer::new(f.text),encoding:f.encoding,line_ending:f.line_ending,had_bom:f.had_bom,dirty:false}}fn session(&self)->SessionTab{SessionTab{path:self.path.clone(),title:self.title.clone(),text:self.buffer.text().into(),cursor:self.buffer.cursor(),metadata:self.buffer.metadata().to_vec(),encoding:self.encoding,line_ending:self.line_ending,had_bom:self.had_bom,modified:self.dirty}}fn from_session(t:SessionTab)->Self{Self{path:t.path,title:t.title,buffer:EditorBuffer::from_parts(t.text,t.metadata,t.cursor),encoding:t.encoding,line_ending:t.line_ending,had_bom:t.had_bom,dirty:t.modified}}}
#[derive(Debug,Clone)]pub struct AppState{pub tabs:Vec<DocumentState>,pub active_tab:usize}impl Default for AppState{fn default()->Self{Self{tabs:vec![DocumentState::default()],active_tab:0}}}impl AppState{fn active(&self)->Option<&DocumentState>{self.tabs.get(self.active_tab)}fn active_mut(&mut self)->Option<&mut DocumentState>{self.tabs.get_mut(self.active_tab)}fn dirty(&self)->bool{self.tabs.iter().any(|t|t.dirty)}}
#[derive(Debug,Clone)]pub struct EditorSnapshot{pub title:String,pub path:Option<PathBuf>,pub text:String,pub metadata:Vec<LineMetadata>,pub cursor:usize,pub scroll_line:usize,pub selection:notepad_core::Selection,pub dirty:bool,pub encoding:TextEncoding,pub line_ending:LineEnding}

pub struct AppController{data_dir:PathBuf,settings_store:SettingsStore,session_store:SessionStore,notes:NotesStore,settings:RwLock<Settings>,recent:Mutex<Vec<PathBuf>>,startup:Mutex<Vec<PathBuf>>,state:Mutex<AppState>,window:RwLock<WindowState>,command:Mutex<Option<WindowCommand>>}
impl AppController{
pub fn new()->Result<Self>{let p=std::env::var_os("NOTEPAD_PRO_DATA_DIR").map(PathBuf::from).or_else(||directories::ProjectDirs::from("com","NotePadPro","NotePad Pro").map(|p|p.data_dir().to_path_buf())).unwrap_or_else(||std::env::temp_dir().join("notepad-pro"));Self::with_data_dir(p)}
pub fn with_data_dir(dir:impl Into<PathBuf>)->Result<Self>{let dir=dir.into();fs::create_dir_all(&dir)?;let ss=SettingsStore::new(dir.join("settings.json"));let session=SessionStore::new(dir.join("session.json"));let settings=ss.load().unwrap_or_default();let recent=fs::read(dir.join("recent.json")).ok().and_then(|b|serde_json::from_slice(&b).ok()).unwrap_or_default();let window=session.load().map(|s|s.window).unwrap_or_default();Ok(Self{data_dir:dir.clone(),settings_store:ss,session_store:session,notes:NotesStore::open(dir.join("notes.sqlite"))?,settings:RwLock::new(settings),recent:Mutex::new(recent),startup:Mutex::new(Vec::new()),state:Mutex::new(AppState::default()),window:RwLock::new(window),command:Mutex::new(None)})}
pub fn data_dir(&self)->&Path{&self.data_dir}
pub fn ping(&self)->String{"pong".into()}pub fn app_info(&self)->AppInfo{AppInfo::default()}pub fn get_settings(&self)->Settings{self.settings.read().map(|s|s.clone()).unwrap_or_default()}
pub fn save_settings(&self,s:Settings)->Result<()>{self.settings_store.save(&s)?;if let Ok(mut x)=self.settings.write(){*x=s.clone()}self.trim_recent(s.recent_files_limit);Ok(())}pub fn update_settings(&self,k:&str,v:Value)->Result<Settings>{let s=self.settings_store.update(k,v)?;if let Ok(mut x)=self.settings.write(){*x=s.clone()}Ok(s)}pub fn theme(&self)->Theme{Theme::from_name(&self.get_settings().theme)}
pub fn get_recent_files(&self)->Vec<String>{self.recent.lock().map(|v|v.iter().map(|p|p.display().to_string()).collect()).unwrap_or_default()}pub fn clear_recent_files(&self){if let Ok(mut v)=self.recent.lock(){v.clear()}let _=fs::remove_file(self.data_dir.join("recent.json"));}
pub fn save_session(&self,mut s:SessionData)->Result<()>{if let Ok(st)=self.state.lock(){s.tabs=st.tabs.iter().map(DocumentState::session).collect();s.active_tab=st.active_tab}s.window=self.window_state();self.session_store.save(&s)}pub fn load_session(&self)->Result<SessionData>{self.session_store.load()}pub fn restore_session(&self,s:SessionData){if let Ok(mut st)=self.state.lock(){st.tabs=if s.tabs.is_empty(){vec![DocumentState::default()]}else{s.tabs.into_iter().map(DocumentState::from_session).collect()};st.active_tab=s.active_tab.min(st.tabs.len()-1)}if let Ok(mut w)=self.window.write(){*w=s.window}}
pub fn open_file_dialog(&self)->Result<Vec<PathBuf>>{Ok(FileDialog::new().set_title("Open files").pick_files().unwrap_or_default())}pub fn load_file(&self,p:impl AsRef<Path>)->Result<LoadedFile>{FileManager::load_file(p)}pub fn save_file(&self,p:impl AsRef<Path>,text:&str,e:TextEncoding,l:LineEnding)->Result<()>{FileManager::save_file(p,text,e,l)}pub fn save_file_as(&self,text:&str,name:&str)->Result<Option<PathBuf>>{let p=FileDialog::new().set_title("Save note").set_file_name(name).save_file();if let Some(p)=p{self.save_file(&p,text,TextEncoding::Utf8,LineEnding::Lf)?;Ok(Some(p))}else{Ok(None)}}pub fn file_exists(&self,p:impl AsRef<Path>)->bool{p.as_ref().is_file()}pub fn save_extracted_text(&self,text:&str,name:&str)->Result<Option<PathBuf>>{let p=FileDialog::new().set_title("Export extracted text").set_file_name(name).save_file();if let Some(p)=p{FileManager::save_extracted_text(&p,text)?;Ok(Some(p))}else{Ok(None)}}
pub fn set_startup_files(&self,p:Vec<String>){if let Ok(mut x)=self.startup.lock(){*x=p.into_iter().map(PathBuf::from).collect()}}pub fn get_startup_files(&self)->Vec<String>{self.startup.lock().map(|mut x|x.drain(..).map(|p|p.display().to_string()).collect()).unwrap_or_default()}
pub fn get_notes_list(&self,q:Option<&str>)->Result<Vec<Note>>{self.notes.get_notes_list(q)}pub fn get_note(&self,id:i64)->Result<NoteData>{self.notes.get_note(id)?.map(NoteData::from).ok_or_else(||notepad_core::CoreError::InvalidValue(format!("note {id} does not exist")))}pub fn save_note(&self,n:NoteData)->Result<i64>{self.notes.save_note(&n)}pub fn delete_note(&self,id:i64)->Result<()>{self.notes.delete_note(id)}pub fn toggle_pin(&self,id:i64)->Result<bool>{self.notes.toggle_pin(id)}
pub fn highlight_stats(&self)->HighlightStats{self.state.lock().ok().and_then(|s|s.active().map(|d|notepad_core::highlight_stats(d.buffer.text(),d.buffer.metadata()))).unwrap_or_else(||notepad_core::highlight_stats("",&[]))}pub fn extract_by_colour(&self,c:Vec<LineColour>,o:ColorOrder)->String{self.state.lock().ok().and_then(|s|s.active().map(|d|notepad_core::extract_by_colour(d.buffer.text(),d.buffer.metadata(),&c,o))).unwrap_or_default()}pub fn copy_to_clipboard(&self,text:String)->Result<()>{let mut c=arboard::Clipboard::new().map_err(|e|notepad_core::CoreError::InvalidValue(e.to_string()))?;c.set_text(text).map_err(|e|notepad_core::CoreError::InvalidValue(e.to_string()))}pub fn paste_from_clipboard(&self)->Result<Option<String>>{let mut c=arboard::Clipboard::new().map_err(|e|notepad_core::CoreError::InvalidValue(e.to_string()))?;Ok(c.get_text().ok())}
pub fn window_state(&self)->WindowState{self.window.read().map(|w|*w).unwrap_or_default()}pub fn set_window_state(&self,w:WindowState){if let Ok(mut x)=self.window.write(){*x=w}}pub fn minimise(&self){self.set_command(WindowCommand::Minimize)}pub fn toggle_maximise(&self){self.set_command(WindowCommand::ToggleMaximize)}pub fn confirm_close(&self){self.set_command(WindowCommand::Close)}pub fn close_window(&self)->bool{let dirty=self.state.lock().map(|s|s.dirty()).unwrap_or(false);if dirty{self.set_command(WindowCommand::ConfirmClose);false}else{self.set_command(WindowCommand::Close);true}}pub fn take_window_command(&self)->Option<WindowCommand>{self.command.lock().ok()?.take()}
pub fn active_snapshot(&self)->Option<EditorSnapshot>{self.state.lock().ok()?.active().map(|d|EditorSnapshot{title:d.title.clone(),path:d.path.clone(),text:d.buffer.text().into(),metadata:d.buffer.metadata().to_vec(),cursor:d.buffer.cursor(),scroll_line:0,selection:d.buffer.selection(),dirty:d.dirty,encoding:d.encoding,line_ending:d.line_ending})}pub fn tab_summaries(&self)->Vec<(String,bool)>{self.state.lock().map(|s|s.tabs.iter().map(|d|(d.title.clone(),d.dirty)).collect()).unwrap_or_default()}pub fn active_tab_index(&self)->usize{self.state.lock().map(|s|s.active_tab).unwrap_or(0)}
pub fn open_document(&self,p:impl AsRef<Path>)->Result<()>{let f=self.load_file(p)?;self.remember(&f.path);let mut loaded=DocumentState::loaded(f);loaded.buffer.recognise_list_prefixes(self.get_settings().tab_width as usize);if let Ok(mut s)=self.state.lock(){let empty=s.active().is_some_and(|d|d.path.is_none()&&d.buffer.text().is_empty()&&!d.dirty);if empty{*s.active_mut().expect("active")=loaded}else{s.tabs.push(loaded);s.active_tab=s.tabs.len()-1}}Ok(())}pub fn new_tab(&self){if let Ok(mut s)=self.state.lock(){s.tabs.push(DocumentState::default());s.active_tab=s.tabs.len()-1}}pub fn switch_tab(&self,i:usize)->bool{if let Ok(mut s)=self.state.lock(){if i<s.tabs.len(){s.active_tab=i;return true}}false}
pub fn insert_text(&self,t:&str){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.insert_text(t);d.dirty=true}}}pub fn replace_active_text(&self,t:&str){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){if d.buffer.text()!=t{let end=d.buffer.text().len();d.buffer.replace_range(0..end,t);d.dirty=true}}}}pub fn replace_selection(&self,t:&str){self.insert_text(t)}pub fn selected_text(&self)->Option<String>{let s=self.state.lock().ok()?;let d=s.active()?;let r=d.buffer.selection().range();d.buffer.text().get(r).map(str::to_owned)}pub fn set_active_selection(&self,anchor:usize,caret:usize){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.set_selection(anchor,caret)}}}pub fn select_all(&self){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.select_all()}}}pub fn move_active_cursor(&self,direction:i32,vertical:bool,extend:bool){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){if vertical{d.buffer.move_vertical(direction,extend)}else{d.buffer.move_horizontal(direction,extend)}}}}pub fn move_active_line_start(&self,extend:bool){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.move_line_start(extend)}}}pub fn move_active_line_end(&self,extend:bool){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.move_line_end(extend)}}}pub fn find_active(&self,query:&str,options:&FindOptions)->Result<Vec<FindMatch>>{let s=self.state.lock().map_err(|_|notepad_core::CoreError::InvalidValue("state lock poisoned".into()))?;let Some(d)=s.active()else{return Ok(Vec::new())};notepad_core::find_all(d.buffer.text(),query,options)}pub fn replace_all_active(&self,query:&str,replacement:&str,options:&FindOptions)->Result<usize>{let (text,new_text)={let s=self.state.lock().map_err(|_|notepad_core::CoreError::InvalidValue("state lock poisoned".into()))?;let Some(d)=s.active()else{return Ok(0)};let (new_text,count)=notepad_core::replace_all(d.buffer.text(),query,replacement,options)?;(d.buffer.text().to_owned(),(new_text,count))};if text==new_text.0{return Ok(0)}let mut s=self.state.lock().map_err(|_|notepad_core::CoreError::InvalidValue("state lock poisoned".into()))?;let Some(d)=s.active_mut()else{return Ok(0)};d.buffer.replace_range(0..text.len(),&new_text.0);d.dirty=true;Ok(new_text.1)}pub fn replace_first_active(&self,query:&str,replacement:&str,options:&FindOptions)->Result<bool>{let (text,new_text)={let s=self.state.lock().map_err(|_|notepad_core::CoreError::InvalidValue("state lock poisoned".into()))?;let Some(d)=s.active()else{return Ok(false)};let (new_text,changed)=notepad_core::replace_first(d.buffer.text(),query,replacement,options)?;(d.buffer.text().to_owned(),(new_text,changed))};if !new_text.1{return Ok(false)}let mut s=self.state.lock().map_err(|_|notepad_core::CoreError::InvalidValue("state lock poisoned".into()))?;let Some(d)=s.active_mut()else{return Ok(false)};d.buffer.replace_range(0..text.len(),&new_text.0);d.dirty=true;Ok(true)}pub fn delete_backward(&self){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.delete_backward();d.dirty=true}}}pub fn delete_forward(&self){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.delete_forward();d.dirty=true}}}pub fn set_active_cursor(&self,p:usize,extend:bool){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.set_cursor(p,extend)}}}pub fn undo(&self)->bool{let Ok(mut s)=self.state.lock()else{return false};let Some(d)=s.active_mut()else{return false};let changed=d.buffer.undo();if changed{d.dirty=true}changed}pub fn redo(&self)->bool{let Ok(mut s)=self.state.lock()else{return false};let Some(d)=s.active_mut()else{return false};let changed=d.buffer.redo();if changed{d.dirty=true}changed}pub fn apply_highlight(&self,c:LineColour){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.apply_colour(c);d.dirty=true}}}pub fn apply_custom_highlight(&self,rgb:u32){self.apply_highlight(LineColour::Custom(rgb&0x00FF_FFFF))}pub fn handle_enter(&self){let w=self.get_settings().tab_width as usize;if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.handle_enter(w);d.dirty=true}}}pub fn handle_tab(&self,shift:bool){if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.buffer.adjust_indent(!shift);d.dirty=true}}}pub fn toggle_checkbox(&self,line:usize)->Option<bool>{self.state.lock().ok()?.active_mut().and_then(|d|{let r=d.buffer.toggle_checkbox(line);if r.is_some(){d.dirty=true}r})}
pub fn autosave(&self)->Result<bool>{if !self.get_settings().autosave{return Ok(false)}self.save_active()}pub fn save_active(&self)->Result<bool>{let (p,t,e,l,bom)={let s=self.state.lock().map_err(|_|notepad_core::CoreError::InvalidValue("state lock poisoned".into()))?;let Some(d)=s.active()else{return Ok(false)};let Some(p)=d.path.clone()else{return Ok(false)};(p,d.buffer.text().to_owned(),d.encoding,d.line_ending,d.had_bom)};FileManager::save_file_with_bom(&p,&t,e,l,bom)?;if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.dirty=false}}Ok(true)}pub fn save_active_as(&self)->Result<Option<PathBuf>>{let(t,n)={let s=self.state.lock().map_err(|_|notepad_core::CoreError::InvalidValue("state lock poisoned".into()))?;let Some(d)=s.active()else{return Ok(None)};(d.buffer.text().to_owned(),d.title.clone())};let Some(p)=self.save_file_as(&t,&n)?else{return Ok(None)};self.remember(&p);if let Ok(mut s)=self.state.lock(){if let Some(d)=s.active_mut(){d.path=Some(p.clone());d.title=p.file_name().and_then(|n|n.to_str()).unwrap_or("Untitled").into();d.dirty=false}}Ok(Some(p))}
fn set_command(&self,c:WindowCommand){if let Ok(mut x)=self.command.lock(){*x=Some(c)}}fn remember(&self,p:&Path){if let Ok(mut v)=self.recent.lock(){v.retain(|x|x!=p);v.insert(0,p.into());v.truncate(self.get_settings().recent_files_limit);let _=fs::write(self.data_dir.join("recent.json"),serde_json::to_vec_pretty(&*v).unwrap_or_default());}}fn trim_recent(&self,n:usize){if let Ok(mut v)=self.recent.lock(){v.truncate(n);let _=fs::write(self.data_dir.join("recent.json"),serde_json::to_vec_pretty(&*v).unwrap_or_default());}}
}
